					<view :class="formats.marginTop ? 'ql-active' : ''" class="iconfont icon-722bianjiqi_duanqianju"
						data-name="marginTop" data-value="20px"></view>
					<view :class="formats.previewarginBottom ? 'ql-active' : ''" class="iconfont icon-723bianjiqi_duanhouju"
						data-name="marginBottom" data-value="20px">
					</view>
					<view class="iconfont icon-clearedformat" @tap="removeFormat"></view>
					<view :class="formats.fontFamily ? 'ql-active' : ''" class="iconfont icon-font" data-name="fontFamily"
						data-value="Pacifico"></view>
					<view :class="formats.fontSize === '24px' ? 'ql-active' : ''" class="iconfont icon-fontsize"
						data-name="fontSize" data-value="24px"></view>

					<view :class="formats.color === '#0000ff' ? 'ql-active' : ''" class="iconfont icon-text_color"
						data-name="color" data-value="#0000ff"></view>
					<view :class="formats.backgroundColor === '#00ff00' ? 'ql-active' : ''"
						class="iconfont icon-fontbgcolor" data-name="backgroundColor" data-value="#00ff00"></view>

					<view class="iconfont icon-date" @tap="insertDate"></view>
					<view class="iconfont icon--checklist" data-name="list" data-value="check"></view>
					<view :class="formats.list === 'ordered' ? 'ql-active' : ''" class="iconfont icon-youxupailie"
						data-name="list" data-value="ordered"></view>
					<view :class="formats.list === 'bullet' ? 'ql-active' : ''" class="iconfont icon-wuxupailie"
						data-name="list" data-value="bullet"></view>
					<view class="iconfont icon-undo" @tap="undo"></view>
					<view class="iconfont icon-redo" @tap="redo"></view>

					<view class="iconfont icon-outdent" data-name="indent" data-value="-1"></view>
					<view class="iconfont icon-indent" data-name="indent" data-value="+1"></view>
					<view class="iconfont icon-fengexian" @tap="insertDivider"></view>
					<view class="iconfont icon-charutupian" @tap="insertImage"></view>
					<view :class="formats.header === 1 ? 'ql-active' : ''" class="iconfont icon-format-header-1"
						data-name="header" :data-value="1"></view>
					<view :class="formats.script === 'sub' ? 'ql-active' : ''" class="iconfont icon-zitixiabiao"
						data-name="script" data-value="sub"></view>
					<view :class="formats.script === 'super' ? 'ql-active' : ''" class="iconfont icon-zitishangbiao"
						data-name="script" data-value="super"></view>
					<view class="iconfont icon-shanchu" @tap="clear"></view>
					<view :class="formats.direction === 'rtl' ? 'ql-active' : ''" class="iconfont icon-direction-rtl"
						data-name="direction" data-value="rtl"></view>

				</view>

				<editor id="editor" class="ql-container" placeholder="开始输入..." showImgSize showImgToolbar showImgResize
					@statuschange="onStatusChange" :read-only="readOnly" @ready="onEditorReady" @input="onEditorInput">
				</editor>
			</view>
		</view>

	</view>
</template>

<script setup>
import { useCommonStore } from '@/store';
import { ChooseImageAsync } from '@/utils/comm';
import { Upload } from '@/utils/http';
import { getCurrentInstance, nextTick, ref, watch } from 'vue';

// 获取store
const store = useCommonStore();

// 获取组件实例
const instance = getCurrentInstance();

// 定义props
const props = defineProps({
	modelValue: {
		type: String,
		default: ''
	},
	readOnly: {
		type: Boolean,
		default: false
	}
});

// 定义emit
const emit = defineEmits(['update:modelValue', 'contentChange']);

// 编辑器状态
const formats = ref({});
const content = ref('');
const editorCtx = ref(null);
const editorReady = ref(false);
const setContentRetryCount = ref(0); // 设置内容重试次数
const editorReadyRetryCount = ref(0); // 编辑器就绪重试次数
const MAX_RETRY_COUNT = 10; // 最大重试次数
const MAX_EDITOR_READY_RETRY = 10; // 编辑器就绪最大重试次数

// 监听外部 modelValue 变化
watch(() => props.modelValue, (newValue, oldValue) => {
	// 只有当新值与当前内容不同时才更新（避免重复设置）
	const newContent = newValue || '';
	const currentContent = content.value || '';

	if (newContent === currentContent) {
		return; // 内容相同，不需要更新
	}

	// 如果编辑器已就绪，则更新编辑器内容
	if (editorReady.value && editorCtx.value) {
		setContentRetryCount.value = 0; // 重置重试次数
		setContent(newContent);
	} else {
		// 编辑器还未就绪，等待编辑器就绪后再设置
		// 这个逻辑已经在 onEditorReady 中处理了
		// 但为了确保，我们也可以在这里等待
		const checkEditorReady = () => {
			if (editorReady.value && editorCtx.value) {
				setContentRetryCount.value = 0;
				setContent(newContent);
			} else if (setContentRetryCount.value < MAX_RETRY_COUNT) {
				setContentRetryCount.value++;
				setTimeout(checkEditorReady, 200);
			}
		};
		checkEditorReady();
	}
}, { immediate: true }); // 立即执行，确保初始化时也能触发

// 编辑器准备就绪
const onEditorReady = () => {
	// 如果已经就绪，不再重复初始化
	if (editorReady.value && editorCtx.value) {
		return;
	}

	// 检查重试次数
	if (editorReadyRetryCount.value >= MAX_EDITOR_READY_RETRY) {
		console.error('富文本编辑器：初始化失败，已达到最大重试次数');
		return;
	}

	// 使用 nextTick 确保 DOM 完全渲染后再获取上下文
	nextTick(() => {
		// 延迟一点时间，确保编辑器元素完全渲染
		setTimeout(() => {
			try {
				// 在小程序中，需要指定 in 参数来指定查询范围
				// 尝试多种方式获取组件实例
				let componentInstance = instance;
				// #ifdef MP-WEIXIN || MP-ALIPAY || MP-BAIDU || MP-TOUTIAO || MP-QQ
				// 在小程序中，可能需要使用 proxy 或 ctx
				if (instance && instance.proxy) {
					componentInstance = instance.proxy;
				} else if (instance && instance.ctx) {
					componentInstance = instance.ctx;
				}
				// #endif

				// 创建查询对象
				let query = uni.createSelectorQuery();
				// 如果组件实例存在，则指定 in 参数
				if (componentInstance) {
					query = query.in(componentInstance);
				}
				const selectQuery = query.select('#editor');

				// selectQuery 总是返回一个对象，不会为 null
				// 真正的问题可能在 context 回调中
				selectQuery.context((res) => {
					// 检查返回结果是否有效
					if (!res || !res.context) {
						editorReadyRetryCount.value++;
						if (editorReadyRetryCount.value < MAX_EDITOR_READY_RETRY) {
							console.warn(`富文本编辑器：获取上下文失败，将重试 (${editorReadyRetryCount.value}/${MAX_EDITOR_READY_RETRY})`, res);
							// 重试
							setTimeout(() => {
								onEditorReady();
							}, 300);
						} else {
							console.error('富文本编辑器：获取上下文失败，已达到最大重试次数', res);
						}
						return;
					}

					// 成功获取上下文
					editorCtx.value = res.context;
					editorReady.value = true;
					editorReadyRetryCount.value = 0; // 重置重试次数

					// 如果有初始内容，设置内容
					// 再次延迟，确保编辑器上下文完全就绪
					setTimeout(() => {
						if (props.modelValue) {
							setContentRetryCount.value = 0; // 重置重试次数
							setContent(props.modelValue);
						}
					}, 200);
				}).exec();
			} catch (error) {
				editorReadyRetryCount.value++;
				if (editorReadyRetryCount.value < MAX_EDITOR_READY_RETRY) {
					console.warn(`富文本编辑器：初始化异常，将重试 (${editorReadyRetryCount.value}/${MAX_EDITOR_READY_RETRY}):`, error);
					setTimeout(() => {
						onEditorReady();
					}, 300);
				} else {
					console.error('富文本编辑器：初始化异常，已达到最大重试次数:', error);
				}
			}
		}, 200);
	});
};

// 撤销
const undo = () => {
	editorCtx.value.undo();
};

// 重做
const redo = () => {
	editorCtx.value.redo();
};

// 格式化
const format = (e) => {
	let { name, value } = e.target.dataset;
	if (!name) return;
	editorCtx.value.format(name, value);
};

// 状态变化
const onStatusChange = (e) => {
	formats.value = e.detail;
};

// 编辑器输入事件 - 实时更新内容
const onEditorInput = () => {
	if (!editorCtx.value || !editorReady.value) return;

	editorCtx.value.getContents({
		success: ({ html, text, delta }) => {
			content.value = html;
			emit('update:modelValue', html);
			emit('contentChange', { html, text, delta });
		}
	});
};

// 插入分割线
const insertDivider = () => {
	editorCtx.value.insertDivider({
		success: function () {

		}
	});
};

// 清空内容
const clear = () => {
	editorCtx.value.clear({
		success: function (res) {

		}
	});
};

// 移除格式
const removeFormat = () => {
	editorCtx.value.removeFormat();
};

// 插入日期
const insertDate = () => {
	const date = new Date();
	const formatDate = `${date.getFullYear()}/${date.getMonth() + 1}/${date.getDate()}`;
	editorCtx.value.insertText({
		text: formatDate
	});
};

// 插入图片
const insertImage = async () => {
	try {
		const { tempFilePaths, tempFiles } = await ChooseImageAsync(1);

		if (tempFilePaths && tempFilePaths.length > 0) {
			const { Data } = await Upload(tempFilePaths[0]);

			editorCtx.value.insertImage({
				src: Data[0].Url,
				alt: '图像',
				success: function () {

				}
			});
		}
	} catch (error) {
		console.error('插入图片失败:', error);
	}
};

// 获取内容
const getContent = async () => {
	return new Promise((resolve, reject) => {
		editorCtx.value.getContents({
			success: async ({ html, text, delta }) => {

				content.value = html;
				emit('update:modelValue', html);
				emit('contentChange', { html, text, delta });
				resolve(html);
			},
			fail: (err) => {
				reject(err);
			}
		});
	});
};

// 设置内容
const setContent = (text) => {
	// 如果编辑器还未就绪，等待一段时间后重试
	if (!editorCtx.value || !editorReady.value) {
		setContentRetryCount.value++;
		// 如果超过最大重试次数，停止重试
		if (setContentRetryCount.value > MAX_RETRY_COUNT) {
			console.warn('富文本编辑器设置内容失败：编辑器未就绪');
			setContentRetryCount.value = 0;
			return;
		}
		// 等待一段时间后重试
		setTimeout(() => {
			setContent(text);
		}, 300);
		return;
	}

	// 重置重试次数
	setContentRetryCount.value = 0;

	// 如果内容为空或未定义，设置为空字符串
	const contentToSet = text || '';

	editorCtx.value.setContents({
		html: contentToSet,
		success: () => {
			// 更新本地内容，避免 watch 重复触发
			content.value = contentToSet;
		},
		fail: (err) => {
			console.error('富文本编辑器设置内容失败:', err);
		}
	});
};

// 对外暴露方法
defineExpose({
	getContent,
	setContent,
	clear,
	undo,
	redo
});
</script>

